export default function p(c){const a=[...c.children],s=a.findIndex(e=>e.querySelector("h2")),n=a.findIndex(e=>e.querySelector("ul"));if(n<0){const e=a.map(t=>t.textContent.trim().length>0).lastIndexOf(!0);a.forEach((t,l)=>{const m=t.textContent.trim(),h=l===e&&l>s+1&&m.length<40;!m||h?t.hidden=!0:l<s?t.className="las-intro-label":l>s&&(t.className="las-intro-body")});return}const i=a[n-1],f=i&&n-1>s&&(n-1>s+1||i.textContent.trim().length<40),r=f?n-1:n;a.forEach((e,t)=>{t===s||t===n||(t===r&&f?e.className="las-intro-cardlabel":e.className=t<s?"las-intro-label":"las-intro-body")});const o=document.createElement("div");o.className="las-intro-copy",a.slice(0,r).forEach(e=>o.append(e));const d=document.createElement("div");d.className="las-intro-card",a.slice(r).forEach(e=>d.append(e)),c.append(o,d),c.classList.add("las-intro-ready")}
